import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter/painting.dart';
import 'package:flutter_test/flutter_test.dart';

/// Pictures of known shapes for tests that need real photos on screen. The
/// test binding answers every network request with an error, so a screen
/// under test would only ever show its "no photo" fallback.
///
/// Use the addresses as `imageUrl`s:
///  * [squarePhoto]  800 x 800
///  * [widePhoto]    1200 x 600
///  * [tinyPhoto]    60 x 60 (smaller than any place it is shown in)
class FakePhotos {
  FakePhotos._();

  static const squarePhoto = 'http://photos.test/square.png';
  static const widePhoto = 'http://photos.test/wide.png';
  static const tinyPhoto = 'http://photos.test/tiny.png';

  static final _pictures = <String, Uint8List>{
    squarePhoto: base64Decode(
      '',
    ),
    widePhoto: base64Decode(
      '',
    ),
    tinyPhoto: base64Decode(
      'iVBORw0KGgoAAAANSUhEUgAAADwAAAA8CAIAAAC1nk4lAAAASUlEQVR42u3OAQkAAAgDsAcziYmNZQtBGCzAUj3vRFpaWlpaWlpaWlpaWlpaWlpaWlpaWlpaWlpaWlpaWlpaWlpaWlpaWlr6wgL03zr+xq+oLwAAAABJRU5ErkJggg==',
    ),
  };

  /// Runs [body] with the three pictures served for their addresses; any
  /// other address fails as it does in every test.
  static Future<void> serve(Future<void> Function() body) async {
    debugNetworkImageHttpClientProvider = () => _Client();
    try {
      await body();
    } finally {
      debugNetworkImageHttpClientProvider = null;
    }
  }

  /// Lets the pictures load and appear. They arrive through real I/O, which
  /// the fake clock of a widget test does not run, so this waits for real.
  static Future<void> settle(WidgetTester tester) async {
    for (var i = 0; i < 6; i++) {
      await tester.runAsync(
        () => Future<void>.delayed(const Duration(milliseconds: 150)),
      );
      await tester.pump(const Duration(milliseconds: 100));
    }
  }
}

class _Client extends Fake implements HttpClient {
  @override
  bool autoUncompress = true;

  @override
  Future<HttpClientRequest> getUrl(Uri url) async => _Request(url);
}

class _Request extends Fake implements HttpClientRequest {
  _Request(this.url);

  final Uri url;

  @override
  final HttpHeaders headers = _Headers();

  @override
  Future<HttpClientResponse> close() async {
    final bytes = FakePhotos._pictures[url.toString()];
    return bytes == null ? _Response(const [], 404) : _Response(bytes, 200);
  }
}

class _Headers extends Fake implements HttpHeaders {
  @override
  void add(String name, Object value, {bool preserveHeaderCase = false}) {}

  @override
  void set(String name, Object value, {bool preserveHeaderCase = false}) {}
}

class _Response extends Fake implements HttpClientResponse {
  _Response(this._bytes, this.statusCode);

  final List<int> _bytes;

  @override
  final int statusCode;

  @override
  int get contentLength => _bytes.length;

  @override
  HttpClientResponseCompressionState get compressionState =>
      HttpClientResponseCompressionState.notCompressed;

  @override
  StreamSubscription<List<int>> listen(
    void Function(List<int>)? onData, {
    Function? onError,
    void Function()? onDone,
    bool? cancelOnError,
  }) => Stream<List<int>>.fromIterable([_bytes]).listen(
    onData,
    onError: onError,
    onDone: onDone,
    cancelOnError: cancelOnError,
  );
}
